package com.code.aon.payroll.geograficas;

import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.FetchType;
import javax.persistence.JoinColumn;
import javax.persistence.ManyToOne;
import javax.persistence.Table;

import com.code.aon.common.ITransferObject;

import java.util.HashSet;
import java.util.Set;

import javax.persistence.CascadeType;
import javax.persistence.Id;
import javax.persistence.OneToMany;

/**
 * Comunidad generated by Expand 2.0.1
 */
@Entity
@Table(name="comunidad")
public class Comunidad  implements ITransferObject {

     private String cdg;
     private String descripcion;
     private Pais pais;
     
     /** provincias. */
  	private Set<Provincia> provincias = new HashSet<Provincia>();

    @Id     
    @Column(name="cdg", unique=true, nullable=false, length=2)
    public String getCdg() {
        return this.cdg;
    }
    
    public void setCdg(String cdg) {
        this.cdg = cdg;
    }
    
	
    @Column(name="descripcion", nullable=false, length=30)
    public String getDescripcion() {
        return this.descripcion;
    }
    
    public void setDescripcion(String descripcion) {
        this.descripcion = descripcion;
    }
    
	@ManyToOne(fetch=FetchType.LAZY)
    @JoinColumn(name="paicom")
    public Pais getPais() {
        return this.pais;
    }
    
    public void setPais(Pais pais) {
        this.pais = pais;
    }
    
    @OneToMany(mappedBy = "comunidad", cascade={CascadeType.REMOVE})
	public Set<Provincia> getProvincias() {
		return provincias;
	}

	public void setProvincias(Set<Provincia> provincias) {
		this.provincias = provincias;
	}

	
}


